"""Regenerate the offline OCSF type/required/enum contract from upstream 1.9.0.

Usage: python tests/fixtures/ocsf/generate_contract.py /path/to/ocsf-schema
This is a test fixture exporter, not a full OCSF schema server: profiles and
extensions are intentionally excluded, as the converters do not emit them.
Source: https://github.com/ocsf/ocsf-schema/tree/1.9.0 (Apache-2.0).
"""

import json
import subprocess
import sys
from pathlib import Path

REVISION = "856d462bd20dc46cc1ffed2dfffe3b91ef0fbeba"


def generate(root):
    assert subprocess.check_output(["git", "-C", str(root), "rev-parse", "HEAD"], text=True).strip() == REVISION
    dictionary = json.loads((root / "dictionary.json").read_text())
    attributes = dictionary["attributes"]
    types = dictionary["types"]["attributes"]
    objects = {json.loads(p.read_text())["name"]: json.loads(p.read_text())
               for directory in ["objects", "events"]
               for p in (root / directory).rglob("*.json")}
    definitions = {}

    def scalar(name):
        bases = {"string_t": "string", "integer_t": "integer", "long_t": "integer",
                 "float_t": "number", "boolean_t": "boolean"}
        if name == "json_t":
            return {}
        if name in bases:
            return {"type": bases[name]}
        if name in types:
            return scalar(types[name].get("type", "string_t"))
        if name == "object":
            return {"type": "object"}
        build(name)
        return {"$ref": f"#/$defs/{name}"}

    def merged(name):
        obj = objects[name]
        attrs = merged(obj["extends"]) if obj.get("extends") else {}
        return {**attrs, **{k: v for k, v in obj["attributes"].items()
                           if k != "$include" and isinstance(v, dict)}}

    def build(name):
        if name in definitions:
            return
        definitions[name] = {}
        properties, required = {}, []
        for key, own in merged(name).items():
            if own.get("profile"):
                continue
            base = attributes.get(key, {})
            spec = base | own
            schema = scalar(spec.get("type", "string_t"))
            enums = {**base.get("enum", {}), **(own.get("enum") or {})}
            if enums:
                schema["enum"] = [int(v) if spec.get("type") in ("integer_t", "long_t") else v for v in enums]
            if spec.get("is_array"):
                schema = {"type": "array", "items": schema}
            properties[key] = schema
            if spec.get("requirement") == "required":
                required.append(key)
        definitions[name] = {"type": "object", "properties": properties,
                             "additionalProperties": False}
        if required:
            definitions[name]["required"] = required

    build("osint_inventory_info")
    # Event identity enums are generated by the OCSF server, rather than
    # declared directly in the inherited base-event attributes.
    props = definitions["osint_inventory_info"]["properties"]
    for key, value in {"class_uid": 5021, "category_uid": 5,
                       "type_uid": 502101, "activity_id": 1}.items():
        props[key] = {"const": value}
    definitions["metadata"]["properties"]["version"] = {"const": "1.9.0"}
    return {"$schema": "https://json-schema.org/draft/2020-12/schema",
            "$comment": f"Derived from ocsf/ocsf-schema@{REVISION}; types, required fields and enums; no profiles/extensions or semantic constraints.",
            "$ref": "#/$defs/osint_inventory_info", "$defs": definitions}


if __name__ == "__main__":
    result = generate(Path(sys.argv[1]))
    Path(__file__).with_name("contract-1.9.0.json").write_text(json.dumps(result, indent=2) + "\n")
